package com.pixelmc.hub.client;

import com.google.gson.*;
import com.pixelmc.hub.client.ui.HubView;
import com.pixelmc.hub.network.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.util.*;

/** Tests the real session scheduler/cache methods with a synthetic transport and owned disk. */
public final class SessionUpdatesCacheChecks {
    static long now;static int checks;static final List<HubNetwork.Request> sent=new ArrayList<>();
    static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
    static Object get(Object o,String name)throws Exception{Field f=ClientHubSession.class.getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    static void set(Object o,String name,Object value)throws Exception{Field f=ClientHubSession.class.getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
    static void call(Object o,String name,Class<?>[] types,Object...args)throws Exception{Method m=ClientHubSession.class.getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(o,args);}
    static void bind(ClientHubSession s)throws Exception{set(null,"current",s);((Set<String>)get(s,"available")).add("updates");}
    static void tick(){now+=1_000_000_000L;ClientHubSession.tick();}
    static HubNetwork.Request last(){return sent.get(sent.size()-1);}
    static void reply(HubNetwork.Request r,JsonObject value){ClientHubSession.receive(new HubNetwork.Response(r.session(),r.id(),r.module(),r.action(),true,value.toString()));}
    static JsonObject q(String id){return UpdatesCacheChecks.query(id,0);}
    static JsonObject read(String id){JsonObject r=new JsonObject(),e=new JsonObject(),c=new JsonObject();e.addProperty("id",id);e.addProperty("title","Owned synthetic update");e.addProperty("body","large immutable body".repeat(1000));e.addProperty("packId","00000000-0000-4000-8000-000000000099");e.addProperty("likesCount",0);r.add("entry",e);c.add("rows",new JsonArray());c.addProperty("total",0);c.addProperty("page",0);r.add("comments",c);return r;}
    static void memory(ClientHubSession s,String action,JsonObject q,JsonObject data)throws Exception{((Map<String,JsonObject>)get(s,"updatesMemory")).put(HubUpdatesCache.key(action,q),data.deepCopy());}
    static void runIo(List<Runnable> tasks){List<Runnable> copy=new ArrayList<>(tasks);tasks.clear();copy.forEach(Runnable::run);}
    public static void main(String[] args)throws Exception{
        String a="00000000-0000-4000-8000-000000000001",b="00000000-0000-4000-8000-000000000002";
        Path root=Files.createTempDirectory("hub-session-updates-");HubUpdatesCache disk=new HubUpdatesCache(root);List<Runnable> io=new ArrayList<>();HubView view=new HubView();
        ClientHubSession s=new ClientHubSession(view,sent::add,()->now,null,io::add,Runnable::run,ignored->{},disk);bind(s);set(s,"updatesIncremental",true);set(s,"managerScopeResolved",true);
        JsonObject manager=UpdatesCacheChecks.manager("00000000-0000-4000-8000-000000000003","manager-A","world1");String scope=HubUpdatesCache.identity(manager);set(s,"updatesScope",scope);
        disk.save(scope,HubUpdatesCache.key("read",q(a)),read(a));memory(s,"read",q(b),read(b));
        s.action("updates","read",q(a));check(sent.isEmpty()&&io.size()==1,"A waits for disk without publishing historical content");
        s.action("updates","read",q(b));check(sent.size()==1&&last().payload().contains(b),"B memory request sends immediately");runIo(io);tick();check(sent.size()==1,"late A disk callback cannot replace newer B memory intent");
        HubNetwork.Request request=last();reply(request,HubUpdatesDelta.encode(read(b),HubUpdatesDelta.parseKnown(HubUpdatesDelta.known(read(b)))));check(!((Map<?,?>)get(s,"updatesMemory")).isEmpty(),"authoritative B response accepted");
        runIo(io);s.action("updates","read",q(a));runIo(io);tick();HubNetwork.Request old=last();check(((Map<?,?>)get(s,"updatesBases")).containsKey(old.id()),"wire read baseline held until response");
        ClientHubSession.receive(new HubNetwork.Response(old.session(),old.id(),"updates",old.action(),false,"记录不存在或不可见"));check(((Map<?,?>)get(s,"updatesMemory")).isEmpty()&&((HubRequestQueue)get(s,"queue")).pendingIds().isEmpty(),"revocation purges cache and invalidates every pending updates ticket");
        reply(old,HubUpdatesDelta.encode(read(a),Set.of()));check(((Map<?,?>)get(s,"updatesMemory")).isEmpty(),"old successful reply after purge cannot revive hidden article");runIo(io);check(disk.load(scope,HubUpdatesCache.key("read",q(a)))==null,"revocation removes durable visible content");
        memory(s,"read",q(a),read(a));memory(s,"read",q(b),read(b));s.action("updates","read",q(a));tick();HubNetwork.Request first=last();s.action("updates","read",q(b));tick();HubNetwork.Request second=last();reply(first,HubUpdatesDelta.encode(read(a),Set.of()));check(!((Map<?,?>)get(s,"updatesBases")).containsKey(first.id()),"UI-stale response releases its large baseline before ticket-null return");reply(second,HubUpdatesDelta.encode(read(b),Set.of()));
        s.action("updates","read",q(a));tick();s.action("updates","read",q(b));tick();now+=11_000_000_000L;ClientHubSession.tick();check(((Map<?,?>)get(s,"updatesBases")).isEmpty(),"expired current and noncurrent baselines both released");
        memory(s,"read",q(a),read(a));JsonObject comment=q(a);comment.remove("commentsPage");comment.addProperty("text","idempotent private comment");comment.addProperty("operationId","00000000-0000-4000-8000-000000000077");s.action("updates","comment",comment);tick();HubNetwork.Request write=last();check(write.action().equals("commentSync")&&!HubProtocol.object(write.payload(),65536).get("known").getAsString().equals("[]"),"comment reuses confirmed read body units");
        ((Map<?,?>)get(s,"updatesBases")).remove(write.id());reply(write,HubUpdatesDelta.encode(read(a),HubUpdatesDelta.parseKnown(HubUpdatesDelta.known(read(a)))));tick();HubNetwork.Request retry=last();JsonObject retryBody=HubProtocol.object(retry.payload(),65536);check(retry.action().equals("commentSync")&&retryBody.get("operationId").getAsString().equals(comment.get("operationId").getAsString())&&retryBody.get("known").getAsString().equals("[]"),"committed comment missing base retries original operationId/action once with empty known");reply(retry,HubUpdatesDelta.encode(read(a),Set.of()));check(!((HubRequestQueue)get(s,"queue")).writing("updates"),"recovered write clears pending with original confirmation action");
        int count=sent.size();for(int i=0;i<500;i++)tick();check(sent.size()==count,"idle cache starts no polling");runIo(io);ClientHubSession.close();check(((Map<?,?>)get(s,"updatesMemory")).isEmpty()&&((HubRequestQueue)get(s,"queue")).pendingIds().isEmpty(),"logout clears in-memory units and pending tickets");reply(retry,HubUpdatesDelta.encode(read(a),Set.of()));check(sent.size()==count,"late logout packet ignored");check(disk.load(scope,HubUpdatesCache.key("read",q(a)))!=null,"logout retains already confirmed disk cache");
        io.clear();sent.clear();HubView fresh=new HubView();ClientHubSession deferred=new ClientHubSession(fresh,sent::add,()->now,null,io::add,Runnable::run,ignored->{},disk);bind(deferred);set(deferred,"updatesIncremental",true);deferred.action("updates","snapshot",new JsonObject());check(sent.isEmpty()&&io.isEmpty(),"updates preload waits for manager identity regardless provider iteration order");call(deferred,"resolveUpdatesScope",new Class<?>[]{JsonObject.class},manager);runIo(io);check(sent.size()==1&&last().action().equals("snapshotSync")&&get(deferred,"updatesScope").equals(scope),"trusted Manager scope resolves before first updates wire request");JsonObject otherManager=manager.deepCopy();otherManager.getAsJsonObject("scope").addProperty("serverId","manager-B");HubNetwork.Request oldIdentity=last();call(deferred,"resolveUpdatesScope",new Class<?>[]{JsonObject.class},otherManager);runIo(io);tick();check(!get(deferred,"updatesScope").equals(scope)&&HubProtocol.object(last().payload(),65536).get("known").getAsString().equals("[]"),"new trusted server identity clears old bases before empty-known negotiation");reply(oldIdentity,HubUpdatesDelta.encode(read(a),Set.of()));check(((Map<?,?>)get(deferred,"updatesMemory")).isEmpty(),"old-identity response cannot enter new scope");ClientHubSession.close();
        sent.clear();ClientHubSession fallback=new ClientHubSession(new HubView(),sent::add,()->now,null,Runnable::run,Runnable::run,ignored->{},disk);bind(fallback);set(fallback,"updatesIncremental",true);fallback.action("updates","snapshot",new JsonObject());call(fallback,"resolveUpdatesScope",new Class<?>[]{JsonObject.class},new JsonObject());check(sent.size()==1&&get(fallback,"updatesScope").equals(""),"manager unavailable resolves session-only fallback instead of indefinite loading");ClientHubSession.close();
        sent.clear();ClientHubSession legacy=new ClientHubSession(new HubView(),sent::add,()->now);bind(legacy);legacy.action("updates","read",q(a));check(last().action().equals("read")&&!last().payload().contains("known"),"old peer retains complete plain DTO request");ClientHubSession.close();
        sent.clear();io.clear();disk.save(scope,HubUpdatesCache.key("read",q(a)),read(a));ClientHubSession likes=new ClientHubSession(new HubView(),sent::add,()->now,null,io::add,Runnable::run,ignored->{},disk);bind(likes);set(likes,"updatesIncremental",true);set(likes,"managerScopeResolved",true);set(likes,"updatesScope",scope);likes.action("updates","read",q(a));JsonObject like=new JsonObject();like.addProperty("id",a);like.addProperty("liked",true);likes.action("updates","like",like);runIo(io);tick();check(sent.size()==1&&last().action().equals("like"),"A disk read then plain like rejects A late IO callback");ClientHubSession.close();
        sent.clear();io.clear();ClientHubSession events=new ClientHubSession(new HubView(),sent::add,()->now,null,io::add,Runnable::run,ignored->{},disk);bind(events);set(events,"updatesIncremental",true);set(events,"managerScopeResolved",true);set(events,"updatesScope",scope);events.action("updates","read",q(a));call(events,"invalidate",new Class<?>[]{String.class},"updates");runIo(io);tick();runIo(io);tick();check(sent.size()==1&&last().action().equals("snapshotSync"),"confirmed event cancels old disk IO before authority refresh snapshot");ClientHubSession.close();
        try(var files=Files.walk(root)){for(Path p:files.sorted(Comparator.reverseOrder()).toList()){if(!p.normalize().toAbsolutePath().startsWith(root.toAbsolutePath().normalize()))throw new AssertionError("Cleanup escaped fixture");Files.delete(p);}}
        System.out.println("SessionUpdatesCacheChecks: "+checks+" lifecycle/order/idempotency assertions passed; no game or live service.");
    }
}
